# filename: scripts/verify_policy.py
"""Card [9] 'Done when': change a threshold in config and decisions change without a redeploy.
Edits config/config.json through a bind mount, so run it with the folder mounted:
  docker compose run --rm --no-deps -v "${PWD}\\config:/config" setup python -m scripts.verify_policy
LOCAL ONLY. Always writes the original bytes back, even on errors or Ctrl+C."""
import argparse, json, os, time, uuid
from collections import Counter

from scripts.stepup_e2e import payment, post      # same builder the step-up and stream checks use

FLAGGED = ("STEP_UP", "DECLINE")


def write(path, data):
    """In-place single write (not rename): works whether compose mounts the folder or just the file.
    Bytes, not text, so Windows line endings survive and git sees no change after restore."""
    with open(path, "wb") as fh:
        fh.write(data)


def send(url, base):
    """One small payment on a brand-new synthetic token -> (decision, was_fallback)."""
    body = payment(base, "dev_policy", 10)
    body["card_token"] = f"tok_policy_{uuid.uuid4().hex[:12]}"   # fresh: no velocity/blocked history
    status, resp = post(url, body)
    if status != 200:
        raise SystemExit(f"/v1/decide returned {status}: {resp}")
    if isinstance(resp, (bytes, str)):
        resp = json.loads(resp)
    fb = bool(resp.get("fallback")) or any(str(r).startswith("FALLBACK") for r in resp.get("reasons") or [])
    return resp["decision"], fb


def wait_for(url, base, want, n, timeout):
    """Send until n non-fallback answers IN A ROW satisfy want(). 'In a row' matters: HAProxy spreads
    requests over the pods and each pod reloads on its own ~2 s timer. Returns (seconds or None, decisions)."""
    t0, streak, seen = time.monotonic(), 0, Counter()
    while time.monotonic() - t0 < timeout:
        time.sleep(0.1)
        d, fb = send(url, base)
        if fb:
            seen["fallback (skipped)"] += 1                  # policy never ran for this one
            continue
        seen[d] += 1
        streak = streak + 1 if want(d) else 0
        if streak >= n:
            return time.monotonic() - t0, seen
    return None, seen


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--url", default="http://haproxy:8080/v1/decide")
    p.add_argument("--cards", default="/data/cards.jsonl")
    p.add_argument("--config", default="/config/config.json")
    p.add_argument("--n", type=int, default=10, help="answers in a row needed per phase")
    p.add_argument("--within-s", type=float, default=10, help="pass mark for a change to take effect")
    a = p.parse_args()
    if not os.path.exists(a.config):
        raise SystemExit(f"{a.config} not found: add  -v \"${{PWD}}\\config:/config\"  to the run command")

    with open(a.config, "rb") as fh:
        original = fh.read()
    changed = json.loads(original)
    changed["policy"]["approve_below"] = 0.0                 # nothing scores below 0 -> nothing approved
    with open(a.cards) as fh:
        base = json.loads(fh.readline())                     # synthetic generator card, never real data
    approve, flagged = (lambda d: d == "APPROVE"), (lambda d: d in FLAGGED)
    timeout = a.within_s * 2

    try:
        t_base, seen = wait_for(a.url, base, approve, a.n, timeout)
        print(f"1 before change   {dict(seen)}")
        if t_base is None:
            raise SystemExit("small payments aren't APPROVE even before the change: paste this line")

        write(a.config, b'{"policy": ')                      # deliberately broken JSON
        time.sleep(5)                                        # > 2 reload cycles
        t_bad, seen = wait_for(a.url, base, approve, a.n, timeout)
        print(f"2 broken edit     {dict(seen)}")

        write(a.config, json.dumps(changed, indent=2).encode())
        t_change, seen = wait_for(a.url, base, flagged, a.n, timeout)
        print(f"3 approve_below=0 {dict(seen)}   took effect after "
              + (f"{t_change:.1f} s" if t_change is not None else f"never ({timeout:.0f} s)"))

        write(a.config, original)
        t_restore, seen = wait_for(a.url, base, approve, a.n, timeout)
        print(f"4 restored        {dict(seen)}   took effect after "
              + (f"{t_restore:.1f} s" if t_restore is not None else f"never ({timeout:.0f} s)"))
    finally:
        write(a.config, original)                            # always leave the file exactly as it was
        print("config.json restored to its original bytes")

    checks = [("broken edit ignored: still answering, still APPROVE", t_bad is not None),
              (f"threshold change took effect within {a.within_s:.0f} s",
               t_change is not None and t_change <= a.within_s),
              (f"restore took effect within {a.within_s:.0f} s",
               t_restore is not None and t_restore <= a.within_s)]
    for name, ok in checks:
        print(("PASS " if ok else "FAIL ") + name)


if __name__ == "__main__":
    main()
